/**
 * Logo oficial da FireControl Gestão, usada no cabeçalho de todo PDF
 * emitido pelo sistema (laudo de inspeção, diagnóstico, etc).
 *
 * É só o ícone (escudo + chama + extintor), recortado da logo completa —
 * o nome "FireControl" já é escrito em texto ao lado no cabeçalho
 * (lib/pdf/documentoBase.ts), então usar só o ícone evita repetir o nome
 * duas vezes e cabe melhor no espaço pequeno do cabeçalho.
 */
export const LOGO_BASE64: string | null =
  "data:image/png;base64,";

/** Formato da imagem (necessário pro jsPDF saber decodificar). */
export const LOGO_FORMATO: "PNG" | "JPEG" = "PNG";
